document.addEventListener('DOMContentLoaded',()=>{fetch('cv.json?v=20260527').then(response=>{if(!response.ok)throw new Error("No se pudo cargar el JSON");return response.json();}).then(data=>{renderPortfolio(data);initInteractions();}).catch(err=>{console.error('Error:',err);document.getElementById('app').innerHTML=`<p style="text-align:center; padding:50px;">Error cargando datos. Revisa la consola (F12).</p>`;});});function renderPortfolio(data){const app=document.getElementById('app');app.innerHTML=`
                <!-- NAVBAR -->
                <nav class="glass-nav">
                    <div class="nav-container">
                        <a href="#profile" class="nav-logo">MA.</a>
                        <button class="nav-toggle" type="button" aria-label="Abrir menú" aria-expanded="false" aria-controls="main-nav-links">
                            <span></span>
                            <span></span>
                            <span></span>
                        </button>
                        <ul class="nav-links" id="main-nav-links">
                            <li><a href="#profile">Inicio</a></li>
                            <li><a href="/experiencia.html">Experiencia</a></li>
                            <li><a href="/servicios.html">Servicios</a></li>
                            <li><a href="/proyectos.html">Proyectos</a></li>
                            <li><a href="mailto:${data.personal.email}" class="btn-contact nav-contact">Contactar</a></li>
                        </ul>
                    </div>
                </nav>

                <!-- HERO / PERFIL -->
                <header id="profile" class="hero-section scroll-trigger">
                    <div class="hero-container">
                        <div class="hero-text">
                            <span class="greeting">Hola, soy</span>
                            <h1>${data.personal.name}</h1>
                            <h2 class="subtitle">${data.personal.role}</h2>
                            <p class="summary">${data.profile}</p>
                            
                            <div class="hero-actions">
                                <a href="${data.personal.linkedinUrl}" target="_blank" rel="noopener noreferrer" class="btn-social">
                                    <i class="fa-brands fa-linkedin"></i> LinkedIn
                                </a>
                                <span class="location-badge">
                                    <i class="fa-solid fa-location-dot"></i> ${data.personal.location}
                                </span>
                            </div>
                        </div>
                        <div class="hero-visual">
                            <div class="image-wrapper">
                                <!-- Si usas foto local cambia la url en el json -->
                                <img src="${data.personal.photoUrl}" alt="${data.personal.name}">
                            </div>
                        </div>
                    </div>
                </header>
            `;}
function initInteractions(){const observer=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');}else{entry.target.classList.remove('is-visible');}});},{threshold:0.15,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll('.scroll-trigger').forEach(el=>observer.observe(el));const navToggle=document.querySelector('.nav-toggle');const navLinks=document.querySelector('.nav-links');if(navToggle&&navLinks){const closeMenu=()=>{navLinks.classList.remove('nav-open');navToggle.classList.remove('is-open');navToggle.setAttribute('aria-expanded','false');navToggle.setAttribute('aria-label','Abrir menú');};navToggle.addEventListener('click',()=>{const isOpen=navLinks.classList.toggle('nav-open');navToggle.classList.toggle('is-open',isOpen);navToggle.setAttribute('aria-expanded',String(isOpen));navToggle.setAttribute('aria-label',isOpen?'Cerrar menú':'Abrir menú');});navLinks.querySelectorAll('a').forEach(link=>{link.addEventListener('click',closeMenu);});window.addEventListener('resize',()=>{if(window.innerWidth>768)closeMenu();});document.addEventListener('keydown',(event)=>{if(event.key==='Escape')closeMenu();});}}
